def maxLengthProduct(words):
    best = {}
    for w in words.split(","):
        m = 0
        for c in w:
            m |= 1 << (ord(c) - 97)
        if len(w) > best.get(m, 0):
            best[m] = len(w)
    items = list(best.items())
    ans = 0
    for i in range(len(items)):
        mi, li = items[i]
        for j in range(i + 1, len(items)):
            mj, lj = items[j]
            if mi & mj == 0 and li * lj > ans:
                ans = li * lj
    return ans
